window.DOSIK=window.DOSIK||{};DOSIK["kb_otsu4_law"]={"1":[{"t":"def","term":"危険物","text":"消防法別表の品名欄に掲げる物品で、同表に定める区分に応じ同表の性質欄に掲げる性質を有するものである"},{"t":"table","title":"品名と区分","head":["品名","区分"],"rows":[["二硫化炭素","特殊引火物に該当する · 特殊引火物に含まれる"],["ガソリン","第1石油類に該当する · 第1石油類に含まれる"],["アセトン","第1石油類である"],["灯油","第2石油類に該当する"],["酢酸","第2石油類である"],["クレオソート油","第3石油類である"]]},{"t":"def","term":"第4石油類","text":"ギヤ―油は、第4石油類に該当する · 第4石油類に、クレオソート油は含まれない"},{"t":"def","term":"自然発火・禁水性物質","text":"アルキルアルミニウムとアルキルリチウムは、どちらも自然発火性物質及び禁水性物質に含まれる"}],"2":[{"t":"table","title":"移送取扱所の許可","head":["設置区域","許可権者"],"rows":[["2以上の都道府県の区域にまたがって設置される移送取扱所","総務大臣"],["消防本部及び消防署を設置していない市町村の区域又は2以上の市町村の区域にまたがって設置される移送取扱所","都道府県知事"],["消防本部及び消防署を設置している一の市町村の区域のみに設置される移送取扱所","市町村長"],["消防本部及び消防署を設置している市町村の区域（移送取扱所を除く）","市町村長"]]},{"t":"vs","title":"完成検査前の使用","cols":[{"name":"設置","items":["製造所等を設置した時は、完成検査を受ける前に使用してはならない"]},{"name":"仮使用","items":["製造所等を変更する場合に、変更工事に係る部分以外の部分の全部又は一部について市町村長等の承認を受け、完成検査を受ける前に、仮に使用すること","完成検査前に、変更の工事に係る部分以外の部分の全部を市町村長等の承認を受けて使用した"]},{"name":"承認","items":["所轄消防長又は消防署長の承認を受ける必要がある"]}]},{"t":"table","title":"貯蔵所の区分","head":["貯蔵所・取扱所","内容"],"rows":[["給油取扱所","ガソリンスタンドは給油取扱所である"],["地下タンク貯蔵所","地下に埋没したタンクに危険物を貯蔵している"],["屋外貯蔵所","屋外貯蔵所では硫黄を扱える"],["屋内タンク貯蔵所","屋内にあるタンクにおいて危険物を貯蔵している"]]}],"3":[{"t":"table","title":"標識と掲示板の大きさ","head":["種類","大きさ"],"rows":[["移動タンク貯蔵所の標識","0.3m平方以上、0.4m平方以下でなければならない"],["移動タンク貯蔵所以外の標識","幅0.3m以上、長さ0.6m以上でなければならない"],["掲示板","幅0.3m以上、長さ0.6m以上でなければならない"]]},{"t":"tree","title":"設備の基準","root":"位置・構造・設備の基準","branches":[["保有空地","簡易タンク貯蔵所は、簡易貯蔵タンクを屋外に設置する場合、保有空地が必要である"],["避雷設備","指定数量の倍数が10以上の場合は、避雷設備を設けなければならない"],["排出設備","可燃性の蒸気などが滞留する場合には、屋外の高所に排出する設備を設けなければならない"],["機械器具","危険物を取り扱う機械器具その他の設備は、危険物のもれ、あふれ又は飛散を防止する構造としなければならない"]]},{"t":"tree","title":"構造と表示","root":"構造・表示","branches":[["地階","地階を設けてはならない"],["不燃材料","壁、床、はり、階段を不燃材料で造らなければならない"],["製造所","見やすい箇所に標識と、防火に関し必要な事項を掲示した掲示板を設けなければならない"],["給油取扱所","「給油中エンジン停止」と表示しなければならない"]]}],"4":[{"t":"tree","title":"貯蔵倉庫","root":"貯蔵倉庫","branches":[["建築物","独立した専用の建築物としなければならない"],["床面積","床面積は1,000m 2以下にしなければならない"],["高さ","地盤面から軒までの高さは6m未満の平屋建としなければならない"],["屋根","屋根は不燃材料で造り、金属板その他の軽量な不燃材料でふき、天井を設けてはならない"]]},{"t":"tree","title":"移動貯蔵タンク","root":"移動貯蔵タンク","branches":[["容量","移動貯蔵タンクの容量は、30,000L以下にしなければならない · タンク容量は30,000L以下とし、内部に4,000L以下ごとに、厚さ3.2mm以上の鋼板で完全な間仕切りを設けなければならない"],["水圧試験","圧力タンク以外のものにあっても、定めれられた水圧試験において、漏れ、又は変形しないものでなければならない"],["接地導線","静電気による災害が発生するおそれのある液体の危険物の移動貯蔵タンクには、接地導線を設けなければならない"],["配管","配管は、先端部に弁等を設けなければならない"],["タンク","タンクは、厚さ3.2mm以上の鋼板で気密に造らなければならない"]]},{"t":"tree","title":"その他の設備","root":"設備","branches":[["漏洩検査管","漏洩検査管を4箇所以上設けなければならない"],["防油堤","防油堤の高さは0.5m以上としなければならない"]]}],"5":[{"t":"tree","title":"販売取扱所","root":"販売取扱所","branches":[["設置","建築物の1階に設置しなければならない"],["配合室の床面積","危険物を配合する室の床面積は、6m 2以上10m 2以下としなければならない"],["配合室の設備","危険物を配合する室は、可燃性の蒸気又は可燃性の微粉を屋根上に排出する設備を設けなければならない"],["標識・掲示板","見やすい箇所に、第1種販売取扱所である旨を表示した標識及び防火に関し必要な事項を掲示した掲示板を設けなければならない"]]},{"t":"tree","title":"顧客用給油取扱所","root":"給油取扱所","branches":[["監視","制御卓で、顧客の給油作業を直視等により、適切に監視しなければならない"],["給油作業の開始","顧客の給油作業が開始されるときは、火気のないこと、その他安全上支障のないことを確認した上で、制御装置を用いてホース機器への危険物の供給を開始し、顧客の給油作業が行える状態にしなければならない"],["給油作業の終了","顧客の給油作業が終了したときは、制御装置を用いてホース機器への危険物の供給を停止し、顧客の給油作業が行えない状態にしなければならない"],["進入時の表示","当該給油取扱所へ進入する際、見やすい箇所に顧客が自ら給油等を行うことができる旨の表示をしなければならない"]]},{"t":"tree","title":"顧客用固定給油設備","root":"顧客用固定給油設備","branches":[["給油量","1回の給油量及び給油時間の上限を、それぞれ顧客の1回あたりの給油量及び給油時間を勘案して、適正に数値を設定しなければならない"],["誤給油","ガソリン及び軽油相互の誤給油を有効に防止することができる構造のものとしなければならない"],["給油ノズル","自動車等の燃料タンクが満量となったときに給油を自動的に停止する構造としなければならない"],["衝突","固定給油設備には、顧客の運転する自動車等が衝突することを防止するための対策を施さなければならない"]]}],"6":[{"t":"tree","title":"貯蔵・取扱いの措置","root":"貯蔵・取扱いの共通基準","branches":[["漏れ","危険物が漏れ、あふれ又は飛散しないように必要な措置を講じなければならない"],["遮光・換気","危険物を貯蔵し、又は取り扱う建築物その他の工作物又は設備は、危険物の性質に応じ、遮光又は換気を行わなければならない"],["温度・湿度","温度計、湿度計等を監視して、危険物の性質に応じた適正な温度又は湿度を保つように貯蔵し、又は取り扱わなければならない"],["電線・工具","可燃性の液体及び可燃性の蒸気等が漏れ又は滞留するおそれのある場所では電線と電気工具とを完全に接続し、かつ火花を発する工具等を使用してはならない"]]},{"t":"tree","title":"廃棄・計量口・販売","root":"貯蔵・取扱いの共通基準","branches":[["くず、かす","危険物のくず、かす等は、1日に1回以上、当該危険物の性質に応じて安全な場所で廃棄その他適当な処置をすること"],["計量口","屋外貯蔵タンク、屋内貯蔵タンク、地下貯蔵タンク又は簡易貯蔵タンクの計量口は、計量するとき以外は閉鎖しておかなければならない"],["販売取扱所","危険物は店舗において容器入りのままで販売しなければならない"]]},{"t":"vs","title":"同時貯蔵","cols":[{"name":"同時貯蔵できない","items":["第1類の危険物と第4類の危険物"]},{"name":"同時貯蔵できる","items":["第4類と第5類の、有機過酸化物又はこれを含有するもの","第1類の危険物と第6類の危険物","第2類の危険物と黄りん又はこれを含有するもの"]}]}],"7":[{"t":"tree","title":"運搬容器","root":"運搬容器","branches":[["表示","運搬容器及び包装の外部に危険物の品名、数量等を表示して積載しなければならない"],["積載","運搬容器は収納口を上に向けて積載しなければならない"],["引火性固体","第2類の危険物のうち、引火性固体にあっては、「火気厳禁」"],["特殊引火物","特殊引火物を運搬する場合は、直射日光をさけるため、遮光性の被覆で覆わなければならない"]]},{"t":"tree","title":"指定数量以上の運搬","root":"指定数量以上の危険物の運搬","branches":[["消火設備","当該危険物に適応する消火設備を備えなければならない"],["標識","当該車両に「危」と表示した標識を掲げなければならない"],["休憩","休憩のため車両を一時停止させるときは、安全な場所を選び、かつ、運搬する危険物の保安に注意しなければならない"]]},{"t":"tree","title":"移送","root":"移送","branches":[["移動タンク貯蔵所","移動タンク貯蔵所によるガソリンの移送は、丙種危険物取扱者を乗車させて、これを行うことができる"],["乗車","危険物を移送する場合は、その危険物を取り扱うことができる危険物取扱者を乗車させなければならない"],["免状","危険物を移送する危険物取扱者は、危険物取扱者免状を携帯しなければならない"]]}],"8":[{"t":"table","title":"消火設備の区分","head":["消火設備","区分"],"rows":[["屋内消火栓設備","第1種消火設備である"],["消火粉末を放射する大型消火器","第4種消火設備である"],["乾燥砂","第5種の消火設備である"]]},{"t":"tree","title":"消火設備の設置","root":"設置","branches":[["地下タンク貯蔵所","第5種の消火設備を2個以上設ける"],["電気設備","電気設備に対する消火設備は、電気設備のある場所の面積100m 2ごとに1個以上設ける"]]}],"9":[{"t":"tree","title":"免状の手続き","root":"免状の手続き","branches":[["書換えの申請先","免状の書換えは、交付を受けた都道府県知事又は居住地若しくは勤務地を管轄する都道府県知事へ申請しなければならない"],["書換えの事例","転職して勤務先が変わったが免状の書換えを申請しなかった"],["申請先","当該免状を交付した都道府県知事に申請することができる · 当該免状の書換えをした都道府県知事に申請することができる"],["再交付","汚損により免状の再交付を申請する場合は、当該免状を添えて申請しなければならない"],["亡失","免状を亡失してその交付を受けた者は、亡失した免状を発見した場合は、これを10日以内に免状の再交付を受けた都道府県知事に提出しなければならない"]]},{"t":"tree","title":"危険物取扱者の資格","root":"危険物取扱者","branches":[["乙種","類について免状があり、免状を受けた類の危険物を取り扱う事ができる"],["甲種の受験","乙種危険物取扱者として2年以上の実務経験があれば、甲種危険物取扱者を受験できる"],["立会い","指定数量未満のガソリンなので、乙種第4類の免状を持つ危険物取扱者が立ち会って危険物を取り扱った"],["危険物施設保安員","危険物施設保安員の立会いがあっても危険物を取り扱えない"]]}],"10":[{"t":"tree","title":"保安講習","root":"保安講習","branches":[["対象者","危険物保安監督者は、受講の対象者となる · 製造所等で危険物の取扱作業に従事している危険物取扱者は、受講の対象者となる"],["受講義務","受講義務のある危険物取扱者が受講しなかったときは、免状返納命令の対象となる"],["場所","免状の交付を受けた都道府県だけでなく、どこの都道府県で行われている講習でも、受講することができる"]]},{"t":"tree","title":"危険物保安監督者","root":"危険物保安監督者","branches":[["選任","製造所等の所有者が定めた · 選任したので、市町村長等に届け出た"],["移動タンク貯蔵所","移動タンク貯蔵所であれば、危険物保安監督者を選任する必要がない"],["解任","市町村長等の判断で、危険物保安監督者の解任を命ぜられる場合がある"]]},{"t":"tree","title":"危険物施設保安員の業務","root":"危険物施設保安員","branches":[["保安管理","計測装置、制御装置、安全装置等の機能が適正に保持されるように保安管理をさせること"],["点検","構造及び設備を技術上の基準に適合するよう、定期及び臨時の点検を行わせること"],["記録","定期及び臨時の点検を行ったときは、点検を行った場所の状況及び保安のために行った措置を記録し、保存させること"],["異常","構造及び設備に異常を発見した場合は、危険物保安監督者その他関係のある者に連絡するとともに状況を判断して適当な措置を講じさせること"]]}],"11":[{"t":"tree","title":"定期点検","root":"定期点検","branches":[["実施者","危険物施設保安員は甲種又は乙種危険物取扱者の立会いがなくても定期点検を行うことができる"],["内容","点検は、製造所等の位置、構造及び設備が技術上の基準に適合しているかどうかについて行う"],["回数","点検は、原則として1年に1回以上行わなければならない"],["記録","点検の結果は、記録し、一定期間保存しなければならない"],["対象","移動タンク貯蔵所及び地下タンクを有する給油取扱所については、すべてこの点検を行わなければならない"]]},{"t":"tree","title":"予防規程","root":"予防規程","branches":[["遵守","所有者等及び従業者は、予防規程を守らなければならない"],["管理","危険物の保安に関する業務を管理する者の職務及び組織に関すること"],["保安教育","危険物の保安に係る作業に従事する者に対する保安教育に関すること"],["運転・操作","危険物施設の運転又は操作に関すること"],["非常の場合","災害その他の非常の場合に取るべき措置に関すること"]]},{"t":"def","term":"定期保安検査","text":"配管の延長が15kmを超える移送取扱所は、完成検査を受けた日または前回の保安検査を受けた日の翌日から原則として1年を経過する日までの前後1ヶ月の間、定期保安検査を行わなければならない"},{"t":"def","term":"製造所","text":"指定数量の10倍以上"}],"12":[{"t":"table","title":"違反の事由","head":["区分","違反したとき"],"rows":[["変更","製造所等の位置・構造・設備を無許可で変更したとき · 変更の許可を受けないで、製造所等の位置、構造又は設備を変更したとき"],["完成検査・使用","製造所等を完成検査済証の交付前に使用したとき · 完成検査又は仮使用の承認を受けないで製造所等を使用したとき · 設置の完成検査を受けないで製造所等を使用したとき"],["定期点検","製造所等の定期点検の実施・記録・保存がなされないとき · 製造所等の定期点検に関する規定に違反したとき · 定期点検が義務づけられている製造所等で、期限内に定期点検を行っていないとき"],["保安監督者","危険物保安監督者を定めたが、その者に危険物の取扱作業に関する保安の監督をさせていないとき · 危険物保安監督者を定めなければならない製造所等で、危険物保安監督者を定めていたが、その者に保安の監督をさせていないとき"],["措置命令","製造所等の位置、構造又は設備に係る措置命令に違反したとき"]]}]};
